SELECT asText(round(tcentroid(temp), 6)) FROM ( VALUES
  (NULL::tnpoint),
  ('Npoint(1, 0.5)@2001-01-01'),
  ('{Npoint(1, 0.3)@2001-01-01, Npoint(1, 0.5)@2001-01-02, Npoint(1, 0.5)@2001-01-03}')) t(temp);
SELECT asText(round(tcentroid(temp), 6)) FROM ( VALUES
  (tnpoint 'Npoint(1, 0.5)@2001-01-01'),
  ('{Npoint(1, 0.3)@2001-01-01, Npoint(1, 0.5)@2001-01-02, Npoint(1, 0.5)@2001-01-03}'),
  (NULL)) t(temp);
SELECT asText(round(tcentroid(temp), 6)) FROM ( VALUES
  (tnpoint '{Npoint(1, 0.3)@2001-01-01, Npoint(1, 0.5)@2001-01-02, Npoint(1, 0.5)@2001-01-03}'),
  ('[Npoint(1, 0.2)@2001-01-01, Npoint(1, 0.4)@2001-01-02, Npoint(1, 0.5)@2001-01-03]')) t(temp);
WITH temp1(k, inst) AS (
  SELECT 1, tnpoint 'Npoint(1, 0.1)@2001-01-01' UNION
  SELECT 2, tnpoint 'Npoint(1, 0.2)@2001-01-02' UNION
  SELECT 3, tnpoint 'Npoint(1, 0.3)@2001-01-03' UNION
  SELECT 4, tnpoint 'Npoint(1, 0.4)@2001-01-04' UNION
  SELECT 5, tnpoint 'Npoint(1, 0.5)@2001-01-05' UNION
  SELECT 6, tnpoint 'Npoint(1, 0.6)@2001-01-06' UNION
  SELECT 7, tnpoint 'Npoint(1, 0.7)@2001-01-07' UNION
  SELECT 8, tnpoint 'Npoint(1, 0.8)@2001-01-08'  ),
temp2(k, seq) AS (
  SELECT k / 3, appendInstant(inst ORDER BY inst)
  FROM temp1
  GROUP BY k / 3)
SELECT astext(appendSequence(seq ORDER BY seq)) FROM temp2;
