-- cbufferset, Text, over tbl_cbufferset
WITH r AS (SELECT DISTINCT ON (q) k, v FROM (SELECT k, v, ntile(4) OVER (ORDER BY k) AS q FROM tbl_cbufferset t(k, v) WHERE v IS NOT NULL) s ORDER BY q, k) SELECT k, asText(v, maxdecimaldigits => 6), cbuffersetFromText(asText(v)) = v AS roundtrip FROM r ORDER BY k;

-- cbufferset, Output, over tbl_cbufferset
